class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # Each quantity is the number of shares belonging to that strategy's
        # private lot.  The two strategies trade different securities.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state series consume every available bar, even on a day on
        # which the full-system missing-data rule prevents signal evaluation.
        if "SPY" in bars:
            self.spy_closes.Add(float(bars["SPY"].Close))
        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            self.aapl_closes.Add(aapl_close)
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        if len(bars) != len(self.symbols):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and self.spy_closes.IsReady:
            spy_ma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            spy_ma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            crossed_below = (
                self.spy_closes[1] >= spy_ma_yesterday
                and self.spy_closes[0] < spy_ma_today
            )
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0 and self.spy_closes.IsReady:
            spy_ma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            spy_ma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            crossed_above = (
                self.spy_closes[1] <= spy_ma_yesterday
                and self.spy_closes[0] > spy_ma_today
            )
            if crossed_above:
                quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_closes.IsReady:
            red_for_three_days = all(
                self.aapl_closes[i] < self.aapl_closes[i + 1]
                for i in range(3)
            )
            if red_for_three_days and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

