            self.aapl_rsi.Update(data.Time, aapl_close)
        else:
            aapl_close = None

        complete_bar = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values())
        indicators_ready = (
            spy_average is not None
            and self.spy_previous_average is not None
            and self.aapl_rsi.IsReady
        )

        if complete_bar and indicators_ready:
            spy_crossed_above = (
                self.spy_previous_close <= self.spy_previous_average
                and spy_close > spy_average
